#include <stdio.h>

static void swap(int *a, int *b)
{
    if (a == NULL || b == NULL) {
        return;
    }
    int saved = *a;
    *a = *b;
    *b = saved;
}

int main(void)
{
    int low = 9;
    int high = 4;
    swap(&low, &high);
    printf("%d %d\n", low, high);
    return 0;
}

